INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_ATTACKED_1','OH, SO YOU WANNA GO TO WAR?!');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_AVAILABLE','Roll Call available - choose a student.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_BLAKE_PROMO','Buh-Lah-Kay');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_BLAKE_PROMO_HELP','+15% Combat Strength during this Roll Call bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_BONUS_END','Class dismissed. The Roll Call bonus has ended.');
