INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CIV','The Substitute Classroom');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CIV5','The Substitute Classroom');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CIV5_HEADING_1','The Substitute Classroom');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CIV5_TEXT_1','A classroom is a small civilization: citizens, borders, taxes paid in homework, and the occasional rebellion over a seating plan. Under Mr. Garvey, the attendance sheet becomes a constitution and the corridor becomes a contested frontier. Room 101 tolerates many things. Correct pronunciation is not one of them.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CIV_PEDIA','A classroom is a small civilization: citizens, borders, taxes paid in homework, and the occasional rebellion over a seating plan. Under Mr. Garvey, the attendance sheet becomes a constitution and the corridor becomes a contested frontier. Room 101 tolerates many things. Correct pronunciation is not one of them.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CLOSE','Close');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CORRECTION_1','Mr. Garvey: "A-A-RON!"[NEWLINE]Student: "It''s pronounced Aaron, sir."[NEWLINE]Mr. Garvey: "YOU DONE MESSED UP, A-A-RON!"');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CORRECTION_2','Mr. Garvey: "DEE-NICE!"[NEWLINE]Student: "Denise."[NEWLINE]Mr. Garvey: "DO YOU WANNA GO TO WAR, DEE-NICE?!"');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CORRECTION_3','Mr. Garvey: "JAY-QUELL-IN!"[NEWLINE]Student: "Jacqueline."[NEWLINE]Mr. Garvey: "INSUBORDINATE AND CHURLISH!"');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CORRECTION_4','Mr. Garvey: "BUH-LAH-KAY!"[NEWLINE]Student: "Blake."[NEWLINE]Mr. Garvey: "YOU WANNA GO TO WAR, BUH-LAH-KAY?!"');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CORRECTION_5','Mr. Garvey: "Timothy?"[NEWLINE]Student: "Present."[NEWLINE]Mr. Garvey: "Thank you."');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_CURRENT','Student: {1_Name} - {2_Num} turns remaining');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DAWN','Mr. Garvey, your class awaits. Beyond Room 101 stretch unruly kingdoms, suspicious seating arrangements, and a world that insists you are saying its name incorrectly. Take attendance, appoint your Hall Monitors, and send every rebellion to the Principal''s Office. Can you build a civilization that will stand the test of time... without correcting you?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DECLARE_1','YOU HAVE BEEN INSUBORDINATE AND CHURLISH FOR THE LAST TIME!');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DEFEAT_1','Class dismissed. But I am writing every one of you up.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DETENTION_DETAIL','Insubordination reset to 0. +20% strength, +20% military Production, Culture from kills. Happiness: -{1_Num}.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DETENTION_END','Maybe tomorrow you''ll learn how to behave.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DETENTION_PROMO','DETENTION!');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DETENTION_PROMO_HELP','+20% Combat Strength during Detention.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DETENTION_START','THAT''S IT! EVERYBODY GETS DETENTION! I WILL SEND YOU TO O-SHAG-HENNESSY''S OFFICE!');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DETENTION_STATUS','[COLOR_NEGATIVE_TEXT]3/3 - DETENTION TRIGGERED! {1_Num} turns left[ENDCOLOR]');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DISABLED','Classroom state could not be read. Check Lua.log before continuing.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DUMMY','Classroom administration');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_DUMMY_HELP','Automatically maintained Roll Call effect.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_FRIENDLY_1','Present and on time. We might get along.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_FURIOUS','Furious');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_GREETING_1','I am Mr. Garvey. I taught for twenty years in the inner city. You will address me correctly.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_HALL_DETENTION_PROMO','No Hall Pass');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_HALL_DETENTION_PROMO_HELP','+10% additional strength for Hall Monitors during Detention.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_HALL_PROMO','Corridor Authority');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_HALL_PROMO_HELP','+15% Combat Strength in friendly territory; friendly military kills grant Culture. Lost on upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_HOSTILE_1','YOU DONE MESSED UP!');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_IRRITATED','Irritated');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_KILL','CLASS DISMISSED. +{1_Num} [ICON_CULTURE] Culture.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_LEADER','Mr. Garvey');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_LEADER_HEADING_1','Mr. Garvey');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_LEADER_PEDIA','Mr. Garvey arrives with twenty years of teaching experience and absolutely no patience for what he considers elaborate student pranks. Aaron, Denise, Jacqueline and Blake discover that their names are now matters of state. Timothy alone understands the diplomatic value of a simple Present. Inspired by the Key & Peele Substitute Teacher sketches, this fictional civilization turns classroom discipline into empire management.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_LEADER_TEXT_1','Mr. Garvey arrives with twenty years of teaching experience and absolutely no patience for what he considers elaborate student pranks. Aaron, Denise, Jacqueline and Blake discover that their names are now matters of state. Timothy alone understands the diplomatic value of a simple Present. Inspired by the Key & Peele Substitute Teacher sketches, this fictional civilization turns classroom discipline into empire management.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_NEUTRAL_1','Is everybody here? No games today.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_NONE','No student bonus active.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_NO_DETENTION','Detention inactive.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_OFFICE','Principal''s Office');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_OFFICE_HELP','Replaces Public School with all ordinary CP benefits. +2 Culture and +2 Production. During DETENTION: +10% Science in this city. Having at least one Office reduces the empire-wide Detention Happiness penalty from -2 to -1; additional Offices do not stack this relief.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_OFFICE_PEDIA','O-Shag-Hennessy''s office is the final destination of every insubordinate student. The paperwork produces Culture, the filing cabinets produce Production, and nobody asks how the principal spells his name.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_OFFICE_STRATEGY','Build Offices for ordinary Public School research plus Culture and Production. The first Office softens Detention''s global penalty. Every Office boosts its own Science during Detention. Captured Offices keep their ordinary benefits; special Detention effects require a human Substitute Classroom owner.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_OPEN','ROLL CALL');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_PATIENCE','Patience: {1_Num}/3 - {2_Status}');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_PEACE','I EXPECT BETTER BEHAVIOUR FROM NOW ON.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_PEACE_1','I EXPECT BETTER BEHAVIOUR FROM NOW ON.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_PENALTY','Detention discipline');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_PENALTY_HELP','Temporary Global Happiness penalty during Detention.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_READY_NOTICE','The class is assembled. Open ROLL CALL when you are ready.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_ROW_1','A-A-Ron (Aaron)[NEWLINE]+15% Production toward military units. 50% chance of a correction.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_ROW_2','Dee-Nice (Denise)[NEWLINE]+15% Culture. 50% chance of a correction.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_ROW_3','Jay-Quell-In (Jacqueline)[NEWLINE]+15% Science. 50% chance of a correction.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_ROW_4','Buh-Lah-Kay (Blake)[NEWLINE]+15% Combat Strength for military units. 50% chance of a correction.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_ROW_5','Timothy (Timothy)[NEWLINE]+10% Production, Gold, Science, Culture and Faith. No corrections.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_RULES','Bonuses last 8 player turns; Roll Call cooldown starts on selection. Corrections resolve once. Kill Culture: 25% of base strength, rounded, minimum 1 per effect.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SELECT','Call on student');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SHORT','Substitute Classroom');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SPY_1','Attendance Inspector 1');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SPY_10','Attendance Inspector 10');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SPY_2','Attendance Inspector 2');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SPY_3','Attendance Inspector 3');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SPY_4','Attendance Inspector 4');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SPY_5','Attendance Inspector 5');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SPY_6','Attendance Inspector 6');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SPY_7','Attendance Inspector 7');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SPY_8','Attendance Inspector 8');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_SPY_9','Attendance Inspector 9');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_STRATEGY','Time Roll Call for your next eight turns. A-A-Ron supports army production; Dee-Nice accelerates policies; Jay-Quell-In drives research; Buh-Lah-Kay strengthens campaigns. Timothy offers a reliable broad economy. Three corrections trigger a short military surge, so preserve forces and build a Principal''s Office before your patience runs out.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_STUDENT_1','A-A-Ron');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_STUDENT_2','Dee-Nice');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_STUDENT_3','Jay-Quell-In');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_STUDENT_4','Buh-Lah-Kay');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_STUDENT_5','Timothy');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_TITLE','ROOM 101 - ATTENDANCE SHEET');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_TRADE_1','That is an acceptable hall pass.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_TRAIT','Insubordinate and Churlish');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_TRAIT_HELP','Conduct Roll Call every 12 player turns, first available 12 turns after founding your capital. Choose one of five students for an 8-turn bonus. Corrections build Insubordination: the third triggers 5 turns of DETENTION (+20% military strength and military Production, Culture from kills, -2 Global Happiness). Timothy never corrects you. Open ROLL CALL for choices and status.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_UNIT','Hall Monitor');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_UNIT_HELP','Replaces Pikeman, retaining all normal CP properties. +15% Combat Strength in friendly territory. Military kills on friendly battle tiles grant Culture equal to 25% of defeated base strength (minimum 1). +10% additional strength during DETENTION. Unique training is lost on upgrade; civilization-wide temporary bonuses continue on eligible upgraded units.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_UNIT_PEDIA','A clipboard, an armband, and a terrifying willingness to report running in the corridor: the Hall Monitor is the mailed fist of classroom order. Uses the standard Pikeman model.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_UNIT_STRATEGY','Defend friendly territory with Hall Monitors. Their territorial strength and Culture rewards make intruders productive lessons. During Detention they gain an extra +10% strength in addition to the empire''s +20%. Upgrade along the normal Pikeman path when their equipment becomes obsolete.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_WAIT','Next Roll Call in {1_Num} turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_GARVEY_WAR','OH, SO YOU WANNA GO TO WAR?!');
